const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dc = ee.Geometry.Point([-77.0369, 38.9072]);
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // 2. Data Acquisition & Check
  let precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(dc);

  const colSize = await precipCol.size().getInfo();
  console.log(`Number of images in collection: ${colSize}`);

  if (colSize === 0) {
    console.log('No precipitation data found for 2018.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Sum all daily precipitation
  const totalPrecip = precipCol.sum();

  // 4. Check pixel count
  const countResult = await totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dc,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = countResult.precipitation;
  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate total precipitation
  const precipResult = await totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dc,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const totalMm = precipResult.precipitation;

  // 6. Validation & Final Answer
  if (totalMm === null || totalMm === undefined || isNaN(totalMm)) {
    console.log('Calculation returned invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const totalInches = totalMm / 25.4;

  console.log(`Total rainfall in 2018: ${totalMm.toFixed(2)} mm (${totalInches.toFixed(2)} inches)`);
  console.log(`Images used: ${colSize}`);

  if (totalInches >= 50) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
